               atd0(1)*cs1*cs3 - atd0(4)*btd0(4)*cs3*s_2 - btd0(1)*cs3*(-cs4 + cs5*ps0(1)) + &
               cs2*(inv_Z*inv_Z)*(atd0(3)*cs7 + atd0(4)*cs6 - cs4*ps0(1) + &
               cs5*cs8)*(btd0(1)*cs8*s_3 + btd0(3)*cs7 + btd0(4)*cs6 - cs1*ps0(1))
         end block
      case (1)
