               (1.0_wp/2.0_wp)*atd2(2, 2, 1)*cs0*inv_Z*s_3 + &
               (1.0_wp/2.0_wp)*atd0(2)*cs0*cs115*cs20*cs314 + (1.0_wp/2.0_wp)*atd1(2, &
               2)*cs0*cs115*cs20*ps0(1)*ps1(2, 1) - cs159*cs167 - cs167*cs313 + cs19*cs316 - &
               cs198*cs299 - cs25*cs312 - cs295*cs35*ps1(2, 1)) + btd1(2, 2)*(atd0(1)*(-cs295*cs49 &
               - cs305) + atd1(2, 1)*cs122 + cs117*cs191 + cs118*ps0(1)*ps1(2, 1) + cs19*cs306 - &
               cs299*cs49 - cs66*cs7 - cs67*cs7) + btd2(2, 2, 2)*cs27 + btd1(2, 3)*(atd1(2, &
               1)*cs296 - atd1(2, 2)*cs85 + 2.0_wp*cs158 + 2.0_wp*cs160 + cs295*cs91 + cs68*cs93 - &
               cs70*cs93 - cs84*ps1(2, 1)) + btd2(2, 2, 3)*cs23 + btd0(4)*(atd1(2, 4)*cs301 - &
               atd2(2, 2, 4)*cs29 + cs129*cs307 - cs168*cs225 + cs19*cs308 - cs226*cs297 + &
               cs226*cs298 + cs226*cs299 + cs226*cs300 + cs312*cs4) + btd1(2, 4)*(atd0(4)*cs301 + &
               atd1(2, 4)*cs105 - cs10*cs168 + cs19*cs304 - cs297*cs45 + cs298*cs45 + cs299*cs45 + &
               cs300*cs45) + btd2(2, 2, 4)*cs24 + cs18*(atd0(1)*cs321 + atd1(2, 1)*cs319 + atd2(2, &
               2, 1)*cs53 + atd0(2)*cs316 + atd1(2, 2)*cs306 - atd2(2, 2, 2)*cs49 + atd2(2, 2, &
               3)*cs50 + atd0(4)*cs308 + atd1(2, 4)*cs304 + atd2(2, 2, 4)*cs45 - cs177*cs299 + &
               cs19*(6.0_wp*cs0*cs156*cs311 + cs0*cs54*ps0(1)*ps2(2, 2, 2)*s_3 + cs0*cs54*ps1(2, &
               1)*ps1(2, 2)*s_3 - cs151*ps2(2, 2, 4) - cs152*cs307 - cs153*ps2(2, 2, 3) - &
               cs155*ps2(2, 2, 1) - cs322*ps1(2, 1)))
            t_f4_rr_radrad_12 = &
               btd0(1)*(atd0(1)*(cs167*cs73 + cs305*ps1(3, 1) + cs320*cs76 - cs37*ps2(2, 3, 1)) + &
               atd1(2, 1)*cs273 - atd2(2, 3, 1)*cs39 + atd1(3, 1)*cs219 + atd0(2)*cs332 + atd1(2, &
               2)*cs267 + atd2(2, 3, 2)*cs36 + atd1(3, 2)*cs197 + atd0(4)*cs325 + cs159*cs77 + &
               cs19*cs335 + cs250*cs77 + cs252*cs65 + cs294*cs65 + cs330*cs9) + btd1(2, 1)*cs277 + &
               btd2(2, 3, 1)*cs28 + btd1(3, 1)*(cs19*cs323 + cs221) + btd0(2)*(atd0(1)*cs332 + &
               atd1(2, 1)*cs271 + atd2(2, 3, 1)*cs36 + atd1(3, 1)*cs220 + atd1(2, 2)*cs264*ps0(1) &
               + atd1(3, 2)*cs188*ps0(1) + atd0(4)*cs324 - cs186*cs287 + cs19*cs334 - &
               cs2*cs68*ps1(3, 1) - cs2*cs80*ps1(2, 1) - cs236*cs288 - cs25*cs330 + cs331*ps1(2, &
               1)) + btd1(2, 2)*cs270 + btd2(2, 3, 2)*cs27 + btd1(3, 2)*cs201 + btd1(2, 3)*cs254 + &
               btd2(2, 3, 3)*cs23 + btd1(3, 3)*cs165 + btd0(4)*(atd0(1)*cs325 + atd0(2)*cs324 - &
               atd1(2, 2)*cs278 - atd1(3, 2)*cs222 + atd1(2, 4)*cs260 - atd2(2, 3, 4)*cs29 + &
               atd1(3, 4)*cs176 + cs129*ps1(2, 4)*ps1(3, 4) + cs172*cs280 + cs19*cs327 + &
               cs225*cs80 + cs226*cs257 + cs279*cs68 + cs330*cs4) + btd1(2, 4)*cs263 + btd2(2, 3, &
               4)*cs24 + btd1(3, 4)*cs179 + cs18*(atd0(1)*cs335 + atd1(2, 1)*cs276 + atd2(2, 3, &
               1)*cs53 + atd1(3, 1)*cs323 + atd0(2)*cs334 + atd1(2, 2)*cs269 - atd2(2, 3, 2)*cs49 &
               + atd1(3, 2)*cs200 - atd1(2, 3)*cs153*cs73 + atd2(2, 3, 3)*cs50 - atd1(3, &
               3)*cs153*cs61 + atd0(4)*cs327 + atd1(2, 4)*cs262 + atd2(2, 3, 4)*cs45 + atd1(3, &
               4)*cs178 + cs19*(6.0_wp*cs0*cs156*cs61*cs73 + cs0*cs54*ps0(1)*ps2(2, 3, 2)*s_3 + &
               cs0*cs54*ps1(2, 1)*ps1(3, 2)*s_3 - cs151*ps2(2, 3, 4) - cs153*ps2(2, 3, 3) - &
               cs155*ps2(2, 3, 1) - cs322*ps1(3, 1) - cs326*ps1(3, 4)))
            f4_rr_radrad(2, 3) = t_f4_rr_radrad_12
            f4_rr_radrad(3, 2) = t_f4_rr_radrad_12
            f4_rr_radrad(3, 3) = &
               btd0(1)*(atd0(1)*(cs336*cs77 + 2.0_wp*cs345*ps1(3, 1) - cs37*ps2(3, 3, 1)) + &
               atd1(3, 1)*(cs358 + cs77*cs94) - atd2(3, 3, 1)*cs39 + atd1(3, 2)*(-cs345 - &
               cs7*cs77) + atd2(3, 3, 2)*cs36 + cs19*cs361 + cs252*cs360 + cs339*cs77 - cs350*cs83 &
               + cs352*cs9 + cs353*cs360) + btd1(3, 1)*(atd0(1)*(cs336*cs53 + cs358) + atd1(3, &
               1)*cs142 + atd0(2)*cs355 + atd1(3, 2)*cs122 + cs19*cs359 + cs339*cs53 + cs78*cs94 + &
               cs79*cs94) + btd2(3, 3, 1)*cs28 + btd0(2)*(atd1(3, 1)*cs355 + &
               (1.0_wp/2.0_wp)*atd2(3, 3, 1)*cs0*inv_Z*s_3 + &
               (1.0_wp/2.0_wp)*atd0(2)*cs0*cs115*cs20*cs354 + (1.0_wp/2.0_wp)*atd1(3, &
               2)*cs0*cs115*cs20*ps0(1)*ps1(3, 1) + cs19*cs357 - cs25*cs352 - cs252*cs255 - &
               cs255*cs353 - cs268*cs339 - cs336*cs35*ps1(3, 1)) + btd1(3, &
               2)*(atd0(1)*(-cs336*cs49 - cs345) + atd1(3, 1)*cs122 + cs117*cs265 + cs19*cs346 + &
               cs331*ps0(1) - cs339*cs49 - cs7*cs78 - cs7*cs79) + btd2(3, 3, 2)*cs27 + btd1(3, &
               3)*(atd1(3, 1)*cs296 - atd1(3, 2)*cs85 + 2.0_wp*cs251 + 2.0_wp*cs253 + cs336*cs91 + &
               cs80*cs93 - cs82*cs93 - cs84*ps1(3, 1)) + btd2(3, 3, 3)*cs23 + btd0(4)*(atd1(3, &
               4)*cs341 - atd2(3, 3, 4)*cs29 + cs129*cs347 + cs19*cs348 - cs256*cs279 - &
               cs280*cs337 + cs280*cs338 + cs280*cs339 + cs280*cs340 + cs352*cs4) + btd1(3, &
               4)*(atd0(4)*cs341 + atd1(3, 4)*cs105 - cs10*cs256 + cs19*cs344 - cs337*cs45 + &
               cs338*cs45 + cs339*cs45 + cs340*cs45) + btd2(3, 3, 4)*cs24 + cs18*(atd0(1)*cs361 + &
               atd1(3, 1)*cs359 + atd2(3, 3, 1)*cs53 + atd0(2)*cs357 + atd1(3, 2)*cs346 - atd2(3, &
               3, 2)*cs49 + atd2(3, 3, 3)*cs50 + atd0(4)*cs348 + atd1(3, 4)*cs344 + atd2(3, 3, &
               4)*cs45 + cs19*(6.0_wp*cs0*cs156*cs351 + cs0*cs54*ps0(1)*ps2(3, 3, 2)*s_3 + &
               cs0*cs54*ps1(3, 1)*ps1(3, 2)*s_3 - cs151*ps2(3, 3, 4) - cs152*cs347 - cs153*ps2(3, &
               3, 3) - cs155*ps2(3, 3, 1) - cs356*cs76) - cs261*cs339)
         end block
      end select

   end subroutine svdw_radpair_eval

   pure module subroutine svdw_radpair_diag_eval(blend_k, s_1, s_2, s_3, ps0, ps1, ps2, atd0, atd1, &
                                          atd2, atdd0, atdd1, atdd2, max_deriv, f2_radrad, &
                                          f3_r_radrad, f4_rr_radrad)
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> One-body blending weight blend_1b
      real(wp), intent(in) :: s_1
      !> Two-body blending weight blend_2b
      real(wp), intent(in) :: s_2
      !> Three-body blending weight blend_3b
      real(wp), intent(in) :: s_3
      !> Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps0(nkind)
      !> Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps1(3, nkind)
      !> Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps2(3, 3, nkind)
      !> Atom-A radius tensor d/dR_a of the order-0 kind tensor from svdw_atom_rad_eval; last index
      !> selects the kind
      real(wp), intent(in) :: atd0(nkind)
      !> Atom-A radius tensor d/dR_a of the order-1 kind tensor from svdw_atom_rad_eval; last index
      !> selects the kind
      real(wp), intent(in) :: atd1(3, nkind)
      !> Atom-A radius tensor d/dR_a of the order-2 kind tensor from svdw_atom_rad_eval; last index
      !> selects the kind
      real(wp), intent(in) :: atd2(3, 3, nkind)
      !> Atom-A second radius tensor d^2/dR_a^2 of the order-0 kind tensor from
      !> svdw_atom_radrad_eval; last index selects the kind
      real(wp), intent(in) :: atdd0(nkind)
      !> Atom-A second radius tensor d^2/dR_a^2 of the order-1 kind tensor from
      !> svdw_atom_radrad_eval; last index selects the kind
      real(wp), intent(in) :: atdd1(3, nkind)
      !> Atom-A second radius tensor d^2/dR_a^2 of the order-2 kind tensor from
      !> svdw_atom_radrad_eval; last index selects the kind
      real(wp), intent(in) :: atdd2(3, 3, nkind)
      !> Highest *spatial* derivative order to compute (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> d^2S/(dR_a dR_b)
      real(wp), intent(out) :: f2_radrad
      !> d^3S/(dr dR_a dR_b)
      real(wp), intent(out) :: f3_r_radrad(3)
      !> d^4S/(dr^2 dR_a dR_b)
      real(wp), intent(out) :: f4_rr_radrad(3, 3)

      !> Assembled blending polynomial Z and its reciprocal
      real(wp) :: Z, inv_Z

      Z = &
         (1.0_wp/6.0_wp)*(ps0(1)*ps0(1)*ps0(1))*s_3 - 1.0_wp/2.0_wp*ps0(1)*ps0(2)*s_3 + ps0(3)*s_1 &
         - 1.0_wp/2.0_wp*ps0(3)*s_2 + (1.0_wp/3.0_wp)*ps0(3)*s_3 + &
         (1.0_wp/2.0_wp)*(ps0(4)*ps0(4))*s_2
      inv_Z = 1.0_wp/Z

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6

            cs0 = ps0(4)*s_2
            cs1 = 1.0_wp/blend_k
            cs2 = cs1*inv_Z
            cs3 = s_1 - 1.0_wp/2.0_wp*s_2 + (1.0_wp/3.0_wp)*s_3
            cs4 = (1.0_wp/2.0_wp)*atd0(2)*s_3
            cs5 = atd0(1)*s_3
            cs6 = (1.0_wp/2.0_wp)*(ps0(1)*ps0(1)) - 1.0_wp/2.0_wp*ps0(2)
            f2_radrad = &
               (1.0_wp/2.0_wp)*atd0(1)*atd0(2)*cs1*inv_Z*s_3 - atd0(1)*cs2*(-cs4 + cs5*ps0(1)) - &
               (atd0(4)*atd0(4))*cs2*s_2 - atdd0(1)*cs2*cs6*s_3 + &
               (1.0_wp/2.0_wp)*atdd0(2)*cs1*inv_Z*ps0(1)*s_3 - atdd0(3)*cs2*cs3 - atdd0(4)*cs0*cs2 &
               + cs1*(inv_Z*inv_Z)*((atd0(3)*cs3 + atd0(4)*cs0 - cs4*ps0(1) + &
               cs5*cs6)*(atd0(3)*cs3 + atd0(4)*cs0 - cs4*ps0(1) + cs5*cs6))
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
            real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26
            real(wp) :: cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39
            real(wp) :: cs40, cs41, cs42, cs43, cs44, cs45, cs46, cs47, cs48, cs49, cs50, cs51, cs52
            real(wp) :: cs53, cs54, cs55, cs56, cs57, cs58

            cs0 = ps0(4)*s_2
            cs1 = 1.0_wp/blend_k
            cs2 = cs1*inv_Z
            cs3 = cs0*cs2
            cs4 = cs2*s_2
            cs5 = s_1 - 1.0_wp/2.0_wp*s_2 + (1.0_wp/3.0_wp)*s_3
            cs6 = cs2*cs5
            cs7 = (1.0_wp/2.0_wp)*s_3
            cs8 = atd0(2)*cs7
            cs9 = ps0(1)*s_3
            cs10 = atd0(1)*cs9
            cs11 = cs10 - cs8
            cs12 = atd0(1)*cs2
            cs13 = (1.0_wp/2.0_wp)*(ps0(1)*ps0(1)) - 1.0_wp/2.0_wp*ps0(2)
            cs14 = cs13*s_3
            cs15 = cs14*cs2
            cs16 = (inv_Z*inv_Z)
            cs17 = atd0(1)*s_3
            cs18 = atd0(3)*cs5 + atd0(4)*cs0 + cs13*cs17 - cs8*ps0(1)
            cs19 = cs2*cs7
            cs20 = cs19*ps0(1)
            cs21 = cs1*cs16
            cs22 = cs21*cs5
            cs23 = atd1(1, 3)*cs22
            cs24 = cs7*ps1(1, 2)
            cs25 = cs0*ps1(1, 4) + cs14*ps1(1, 1) - cs24*ps0(1) + cs5*ps1(1, 3)
            cs26 = atdd0(3)*cs22
            cs27 = -atd0(4)*cs4 + cs1*cs16*cs18*ps0(4)*s_2
            cs28 = cs0*cs21
            cs29 = cs18*cs21
            cs30 = cs29*cs7
            cs31 = cs12*cs7 - cs30*ps0(1)
            cs32 = cs21*cs25
            cs33 = cs32*cs7
            cs34 = -cs24 + cs9*ps1(1, 1)
            cs35 = -cs10*cs2 + cs14*cs29 + cs2*cs8
            cs36 = cs21*s_2
            cs37 = atd0(4)*cs36
            cs38 = cs18*cs36
            cs39 = cs17*cs2
            cs40 = cs2*cs9
            cs41 = cs11*cs21
            cs42 = cs21*cs34
            cs43 = cs21*cs8
            cs44 = cs21*cs7
            cs45 = cs44*ps0(1)
            cs46 = cs14*cs21
            cs47 = 2.0_wp*cs1*cs18*(inv_Z*inv_Z*inv_Z)
            cs48 = atd1(2, 3)*cs22
            cs49 = cs7*ps1(2, 2)
            cs50 = cs0*ps1(2, 4) + cs14*ps1(2, 1) - cs49*ps0(1) + cs5*ps1(2, 3)
            cs51 = -cs49 + cs9*ps1(2, 1)
            cs52 = atd0(1)*cs44
            cs53 = cs21*cs51
            cs54 = atd1(3, 3)*cs22
            cs55 = cs7*ps1(3, 2)
            cs56 = cs0*ps1(3, 4) + cs14*ps1(3, 1) + cs5*ps1(3, 3) - cs55*ps0(1)
            cs57 = -cs55 + cs9*ps1(3, 1)
            cs58 = cs21*cs57
            f2_radrad = &
               (1.0_wp/2.0_wp)*atd0(1)*atd0(2)*cs1*inv_Z*s_3 - (atd0(4)*atd0(4))*cs4 - &
               atdd0(1)*cs15 + (1.0_wp/2.0_wp)*atdd0(2)*cs1*inv_Z*ps0(1)*s_3 - atdd0(3)*cs6 - &
               atdd0(4)*cs3 + cs1*cs16*(cs18*cs18) - cs11*cs12
            f3_r_radrad(1) = &
               atd0(1)*(-atd1(1, 1)*cs40 + atd1(1, 2)*cs19 + cs18*cs42 + cs25*cs41 - cs39*ps1(1, &
               1)) + atd1(1, 1)*cs35 + atd0(2)*(-atd0(1)*cs33 + (1.0_wp/2.0_wp)*atd1(1, &
               1)*cs1*inv_Z*s_3 - cs30*ps1(1, 1)) + atd1(1, 2)*cs31 + atd0(4)*(-atd1(1, 4)*cs4 + &
               cs25*cs37 + cs38*ps1(1, 4)) + atd1(1, 4)*cs27 + atdd0(1)*(cs14*cs32 - cs2*cs34) - &
               atdd1(1, 1)*cs15 + atdd0(2)*((1.0_wp/2.0_wp)*cs1*inv_Z*ps1(1, 1)*s_3 - cs33*ps0(1)) &
               + atdd1(1, 2)*cs20 - atdd1(1, 3)*cs6 + atdd0(4)*(cs25*cs28 - cs4*ps1(1, 4)) - &
               atdd1(1, 4)*cs3 + cs18*cs23 + cs18*(atd0(1)*cs42 + atd1(1, 1)*cs46 - atd1(1, &
               2)*cs45 + atd1(1, 4)*cs28 + cs23 - cs25*cs47 + cs37*ps1(1, 4) - cs43*ps1(1, 1)) + &
               cs25*cs26
            f3_r_radrad(2) = &
               atd0(1)*(-atd1(2, 1)*cs40 + atd1(2, 2)*cs19 + cs18*cs53 - cs39*ps1(2, 1) + &
               cs41*cs50) + atd1(2, 1)*cs35 + atd0(2)*((1.0_wp/2.0_wp)*atd1(2, 1)*cs1*inv_Z*s_3 - &
               cs30*ps1(2, 1) - cs50*cs52) + atd1(2, 2)*cs31 + atd0(4)*(-atd1(2, 4)*cs4 + &
               cs37*cs50 + cs38*ps1(2, 4)) + atd1(2, 4)*cs27 + atdd0(1)*(-cs2*cs51 + cs46*cs50) - &
               atdd1(2, 1)*cs15 + atdd0(2)*((1.0_wp/2.0_wp)*cs1*inv_Z*ps1(2, 1)*s_3 - cs45*cs50) + &
               atdd1(2, 2)*cs20 - atdd1(2, 3)*cs6 + atdd0(4)*(cs28*cs50 - cs4*ps1(2, 4)) - &
               atdd1(2, 4)*cs3 + cs18*cs48 + cs18*(atd0(1)*cs53 + atd1(2, 1)*cs46 - atd1(2, &
               2)*cs45 + atd1(2, 4)*cs28 + cs37*ps1(2, 4) - cs43*ps1(2, 1) - cs47*cs50 + cs48) + &
               cs26*cs50
            f3_r_radrad(3) = &
               atd0(1)*(-atd1(3, 1)*cs40 + atd1(3, 2)*cs19 + cs18*cs58 - cs39*ps1(3, 1) + &
               cs41*cs56) + atd1(3, 1)*cs35 + atd0(2)*((1.0_wp/2.0_wp)*atd1(3, 1)*cs1*inv_Z*s_3 - &
               cs30*ps1(3, 1) - cs52*cs56) + atd1(3, 2)*cs31 + atd0(4)*(-atd1(3, 4)*cs4 + &
               cs37*cs56 + cs38*ps1(3, 4)) + atd1(3, 4)*cs27 + atdd0(1)*(-cs2*cs57 + cs46*cs56) - &
               atdd1(3, 1)*cs15 + atdd0(2)*((1.0_wp/2.0_wp)*cs1*inv_Z*ps1(3, 1)*s_3 - cs45*cs56) + &
               atdd1(3, 2)*cs20 - atdd1(3, 3)*cs6 + atdd0(4)*(cs28*cs56 - cs4*ps1(3, 4)) - &
               atdd1(3, 4)*cs3 + cs18*cs54 + cs18*(atd0(1)*cs58 + atd1(3, 1)*cs46 - atd1(3, &
               2)*cs45 + atd1(3, 4)*cs28 + cs37*ps1(3, 4) - cs43*ps1(3, 1) - cs47*cs56 + cs54) + &
               cs26*cs56
         end block
      case default
